# typed: strict
# frozen_string_literal: true

# Generated by scripts/formula.ts in tab0inc/happen for each release; edits here are overwritten.
class Happen < Formula
  desc "Messaging between you and a supervising Claude Code session"
  homepage "https://github.com/tab0inc/happen-releases"
  license :cannot_represent

  depends_on :macos

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.12.0/happen_0.12.0_darwin_arm64.tar.gz"
      sha256 "3956bc8f1583edb4a078a1df43fda002a6f9c91b80cf08717ee80f0ce02c4ea6"
    else
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.12.0/happen_0.12.0_darwin_amd64.tar.gz"
      sha256 "5b0a9686e1ffcc7e8934487d08eb64ff95e17e4e39c59a26b7393112eb259fbc"
    end
  end

  def install
    bin.install "happen"
  end

  def caveats
    <<~EOS
      Set up this Mac, start the server (it also starts at login), and connect a browser:
        happen open
      Start a chief: tell Claude Code to run happen skill --space <space>
      and follow it, or type in the session:
        ! happen skill --space <space>
    EOS
  end

  service do
    run [opt_bin/"happen", "serve"]
    keep_alive true
    log_path var/"log/happen.log"
    error_log_path var/"log/happen.log"
    environment_variables PATH: std_service_path_env
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/happen version")
  end
end
